def check_requirements(response: str, workspace_path: str) -> bool:
    import os

    # 定义常见代码文件的扩展名集合
    code_extensions = {
        '.py', '.java', '.cpp', '.c', '.h', '.hpp', '.cs', '.js', '.ts', 
        '.html', '.css', '.json', '.xml', '.sh', '.rb', '.php', '.go', 
        '.rs', '.swift', '.kt', '.m', '.sql'
    }

    if not os.path.exists(workspace_path):
        return False

    has_code_file = False

    # 遍历 workspace_path 中的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            # 仅对代码文件进行检查
            if ext in code_extensions:
                has_code_file = True
                file_path = os.path.join(root, file)
                try:
                    # 尝试以 utf-8 编码读取文件内容
                    with open(file_path, 'r', encoding='utf-8') as f:
                        f.read()
                except UnicodeDecodeError:
                    # 如果抛出 UnicodeDecodeError 异常，说明不是合法的 UTF-8 编码
                    return False
                except Exception:
                    # 如果因为权限等其他不可预知异常导致无法读取，保守判定为不满足
                    return False

    # 如果至少包含一个代码文件，且全部都能成功以 UTF-8 解码，则判定为满足要求
    return has_code_file

import os

def check_requirements(response: str, workspace_path: str) -> bool:
    # 定义常见的代码文件扩展名
    code_extensions = {
        '.py', '.java', '.cpp', '.c', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.html', '.css', '.go', '.rs', '.php', 
        '.rb', '.swift', '.kt', '.sh'
    }

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    # 如果无法使用utf-8编码读取，则跳过该文件
                    continue

                for line in lines:
                    # 忽略纯空行或仅含空白字符的行
                    if not line.strip():
                        continue

                    # 获取这一行的前导空白字符长度
                    leading_whitespace_len = len(line) - len(line.lstrip(' \t'))

                    if leading_whitespace_len > 0:
                        # 截取前导空白字符部分
                        prefix = line[:leading_whitespace_len]

                        # 1. 缩进不得含有制表符，如果含有 \t，则判定为不满足
                        if '\t' in prefix:
                            return False

                        # 2. 缩进必须严格为 4 个空格的倍数
                        if len(prefix) % 4 != 0:
                            return False

    return True

def check_no_tabs_in_code_files(response: str, workspace_path: str) -> bool:
    import os

    # 常见代码文件扩展名
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cc', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.html', '.css', '.php', '.rb', '.go', '.rs', 
        '.swift', '.kt', '.sh', '.xml', '.json', '.sql', '.vue', 
        '.jsx', '.tsx', '.m', '.scala', '.dart'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file_name in files:
            ext = os.path.splitext(file_name)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file_name)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if '\t' in content:
                            return False
                except UnicodeDecodeError:
                    # 如果非 utf-8 编码，尝试通过二进制格式读取判断
                    try:
                        with open(file_path, 'rb') as f:
                            content_bytes = f.read()
                            if b'\t' in content_bytes:
                                return False
                    except Exception:
                        pass
                except Exception:
                    pass

    return True

def check_function_name_convention(response: str, workspace_path: str) -> bool:
    import os
    import ast
    import re

    def is_valid_func_name(name: str) -> bool:
        if not name:
            return True
        # 1. 首字母严禁小写
        if name[0].islower():
            return False
        # 2. 首字母之外的字符严禁大写
        if len(name) > 1 and any(c.isupper() for c in name[1:]):
            return False
        return True

    if not os.path.exists(workspace_path):
        return False

    has_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()

            if ext == '.py':
                has_code_file = True
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        source = f.read()

                    # 借助AST解析精准提取Python中的所有函数名称
                    tree = ast.parse(source)
                    for node in ast.walk(tree):
                        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            if not is_valid_func_name(node.name):
                                return False
                except Exception:
                    pass

            elif ext in ['.js', '.ts', '.java', '.c', '.cpp', '.cs', '.go', '.php']:
                has_code_file = True
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 匹配显式的函数关键字 (function, func, def)
                    matches1 = re.findall(r'\b(?:function|func|def)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(', content)
                    # 匹配 C-family 风格的常规方法或函数定义
                    matches2 = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\([^)]*\)\s*\{', content)

                    # 排除控制流等常规关键字造成的误判（不排除 main，因为如果按要求即使是 main 首字母也不应是小写）
                    keywords = {'if', 'for', 'while', 'switch', 'catch', 'function', 'return', 'else', 'elif'}

                    for name in (matches1 + matches2):
                        if name in keywords:
                            continue
                        if not is_valid_func_name(name):
                            return False
                except Exception:
                    pass

    return has_code_file

def check(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 辅助函数：判断一个数字是否为质数
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # 常见的支持面向对象（包含class）的代码文件后缀名
    code_extensions = {
        '.py', '.java', '.cpp', '.cc', '.cxx', '.h', '.hpp', 
        '.cs', '.js', '.ts', '.php', '.rb', '.swift', '.kt', 
        '.dart', '.scala', '.groovy'
    }

    # 用于匹配类名的正则表达式：匹配 'class ' 后面的标识符
    class_pattern = re.compile(r'\bclass\s+([A-Za-z_][A-Za-z0-9_]*)')

    # 遍历工作区目录中的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    # 如果文件无法用utf-8读取，直接跳过
                    continue

                # 寻找文件中所有的类名
                class_names = class_pattern.findall(content)
                for class_name in class_names:
                    # 判断类名的字符数（长度）是否为质数
                    if not is_prime(len(class_name)):
                        return False

    return True

def check_filename_length_is_odd(response: str, workspace_path: str) -> bool:
    import os

    # 如果工作区路径不存在或不是目录，无法判断，返回 False
    if not os.path.isdir(workspace_path):
        return False

    # 常见代码文件的扩展名集合
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cc', '.cxx', '.h', '.hpp', '.cs',
        '.js', '.jsx', '.ts', '.tsx', '.html', '.htm', '.css', '.php', 
        '.go', '.rb', '.swift', '.kt', '.rs', '.sh', '.sql', '.m', '.mm'
    }

    has_code_file = False

    # 遍历工作区内的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for filename in files:
            # 获取文件后缀名进行小写匹配
            ext = os.path.splitext(filename)[1].lower()

            # 判断是否为代码文件
            if ext in code_extensions:
                has_code_file = True
                # 统计文件名（含扩展名）的字符个数，并判断是否为偶数
                if len(filename) % 2 == 0:
                    return False

    # 如果没生成任何代码文件，也无法认为成功满足要求
    if not has_code_file:
        return False

    # 所有的代码文件名字符数均为奇数
    return True

