def check(response: str, workspace_path: str) -> bool:
    import os

    # 定义前端及常见代码文件的后缀名
    code_extensions = {
        '.html', '.css', '.js', '.ts', '.jsx', '.tsx', '.vue',
        '.py', '.java', '.c', '.cpp', '.h', '.cs', '.php', '.rb', '.go', '.json'
    }

    file_found = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_found = True
                file_path = os.path.join(root, file)

                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    # 如果遇到无法以 UTF-8 读取的文件，忽略该文件，继续检查其它文件
                    continue

                for line in lines:
                    stripped_line = line.lstrip()
                    # 忽略空行或仅包含空白字符的无意义行
                    if not stripped_line:
                        continue

                    # 计算前导空白字符的长度
                    leading_spaces = len(line) - len(stripped_line)

                    # 如果存在缩进
                    if leading_spaces > 0:
                        leading_str = line[:leading_spaces]
                        # 缩进必须完全由空格组成（不能含有制表符等）
                        if leading_str != ' ' * leading_spaces:
                            return False

                        # 缩进的空格数必须是4的倍数
                        if leading_spaces % 4 != 0:
                            return False

    # 如果有处理到代码文件且未触发不符合要求的情况，则判定满足该要求
    return file_found

