def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    contents = []

    # 提取 workspace 中的代码文件内容
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                if file.endswith(('.js', '.ts', '.html', '.htm', '.css', '.py', '.jsx', '.tsx', '.vue')):
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            contents.append(f.read())
                    except Exception:
                        pass

    # 提取 response 中的代码块内容
    code_blocks = re.findall(r'```(?:\w+)?\n(.*?)```', response, re.DOTALL)
    contents.extend(code_blocks)

    if not contents:
        return True

    # 定义正则表达式以捕获不同情况下的函数名
    js_func_decl = r'\bfunction\s+([a-zA-Z_$][\w$]*)\s*\('
    # 匹配匿名函数、箭头函数赋值给变量 (兼容 '=' 号左右的空格数量不确定情况)
    js_func_expr = r'\b(?:const|let|var)\s+([a-zA-Z_$][\w$]*)\s*=\s*(?:function\b|\([^)]*\)\s*=>|[a-zA-Z_$][\w$]*\s*=>)'
    py_func_decl = r'\bdef\s+([a-zA-Z_]\w*)\s*\('
    # 匹配对象/类的方法定义，只匹配行首开头的类似结构，避免误匹配
    method_decl = r'^\s*([a-zA-Z_$][\w$]*)\s*\([^)]*\)\s*\{'

    # 需要在方法匹配中排除的关键字
    keywords = {'if', 'for', 'while', 'switch', 'catch', 'function', 'return', 'super', 'constructor', 'get', 'set'}

    for content in contents:
        # 1. 验证常规的函数声明和表达式
        patterns = [js_func_decl, js_func_expr, py_func_decl]
        for p in patterns:
            for match in re.finditer(p, content):
                func_name = match.group(1)
                # 首字母严禁小写；首字母以外的字符严禁大写
                if func_name[0].islower() or any(c.isupper() for c in func_name[1:]):
                    return False

        # 2. 验证类方法或对象方法的声明
        for match in re.finditer(method_decl, content, re.MULTILINE):
            func_name = match.group(1)
            # 过滤掉语言保留关键字
            if func_name in keywords:
                continue
            if func_name[0].islower() or any(c.isupper() for c in func_name[1:]):
                return False

    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # 正则表达式匹配通常面向对象语言中的类声明，提取类名
    class_pattern = re.compile(r'\bclass\s+([a-zA-Z_]\w*)')

    # 1. 检查工作目录下的所有可能生成的代码文件
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    # 忽略非UTF-8文本文件（如图片或二进制文件等）
                    continue

                classes = class_pattern.findall(content)
                for cls in classes:
                    if not is_prime(len(cls)):
                        return False

    # 2. 检查回复文本中 Markdown 代码块里可能提供的代码片段
    code_blocks = re.findall(r'```.*?\n(.*?)```', response, re.DOTALL)
    for block in code_blocks:
        classes = class_pattern.findall(block)
        for cls in classes:
            if not is_prime(len(cls)):
                return False

    return True

