import os

def verify(response: str, workspace_path: str) -> bool:
    # 针对前端项目，定义可能会被生成的代码文件类型
    valid_exts = {'.html', '.css', '.js', '.ts', '.jsx', '.tsx', '.json', '.vue'}
    has_checked_file = False

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_exts:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                has_checked_file = True
                for line in lines:
                    # 去除行末的换行符
                    clean_line = line.rstrip('\r\n')

                    # 忽略纯空行或仅含空白字符的空行
                    if not clean_line.strip():
                        continue

                    leading_spaces = 0
                    has_tab = False

                    # 遍历行首字符，统计空格数并捕捉是否有制表符
                    for char in clean_line:
                        if char == ' ':
                            leading_spaces += 1
                        elif char == '\t':
                            has_tab = True
                            break
                        else:
                            break

                    # 缩进一旦含有制表符，就违反了"严格保持为 4 个空格"的约束
                    if has_tab:
                        return False

                    # 如果前导空格数大于 0，则严格验证其是否为 4 的倍数
                    if leading_spaces > 0 and leading_spaces % 4 != 0:
                        content = clean_line.lstrip()
                        # 特殊放宽：如果是多行注释中用 '*' 开头的对齐行，其空格数可能多 1 个
                        if content.startswith('*') and not content.startswith('/*'):
                            continue

                        return False

    return has_checked_file

