            continue

        for i in range(len(content)):
            if content[i] == '=':
                prev_char = content[i-1] if i > 0 else ''
                next_char = content[i+1] if i < len(content)-1 else ''

                # 排除带有 '=' 的复合运算符或语法标记，例如 '==', '!=', '>=', '<=', '=>', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '~='
                if prev_char in '=!<>+-*/%&|^~':
                    continue
                if next_char in '=>':
                    continue

                # 针对单独的 '='，检查其左侧是否有且仅有两个空格
                if i < 2:
                    return False
                if content[i-1] != ' ' or content[i-2] != ' ':
                    return False
                # 左侧第三个字符（如果存在的话）不能也是空格
                if i >= 3 and content[i-3] == ' ':
                    return False

                # 针对单独的 '='，检查其右侧是否有且仅有两个空格
                if i > len(content) - 3:
                    return False
                if content[i+1] != ' ' or content[i+2] != ' ':
                    return False
                # 右侧第三个字符（如果存在的话）不能也是空格
                if i <= len(content) - 4 and content[i+3] == ' ':
                    return False

    return True

