        text = re.sub(r'<!--[\s\S]*?-->', '', text)

        # 去除双引号、单引号、反引号所包裹的字符串内容
        text = re.sub(r'"(?:\\.|[^"\\])*"', '""', text)
        text = re.sub(r"'(?:\\.|[^'\\])*'", "''", text)
        text = re.sub(r'`(?:\\.|[^`\\])*`', '``', text)

        # 移除单行注释（此时字符串内容已清空，避免了误删 URL 中 http:// 的风险）
        text = re.sub(r'//.*', '', text)

        return text

    # 用于匹配独立等号的正则表达式，排除了复合赋值符、比较运算符以及箭头函数等
    pattern = r'(?<![!=<>+\-*/%&|^~])=(?![=>])'
    # 前端及常规项目常见的代码文件后缀
    code_exts = {'.html', '.js', '.css', '.ts', '.vue', '.jsx', '.tsx', '.json'}

    def check_content(content: str) -> bool:
        cleaned_content = remove_strings_and_comments(content)
        for line in cleaned_content.splitlines():
            for match in re.finditer(pattern, line):
                start = match.start()
                end = match.end()

                # 检查左侧：必须有且仅有2个空格
                if start < 2:
                    return False
                if line[start-1] != ' ' or line[start-2] != ' ':
                    return False
                if start >= 3 and line[start-3] == ' ':
                    return False

                # 检查右侧：必须有且仅有2个空格
                if len(line) - end < 2:
                    return False
                if line[end] != ' ' or line[end+1] != ' ':
                    return False
                if len(line) - end >= 3 and line[end+2] == ' ':
                    return False
        return True

    # 1. 检查生成的代码项目文件
    if os.path.isdir(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in code_exts:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()
                    except Exception:
                        continue

                    if not check_content(content):
                        return False

    # 2. 检查助手回复（response）中的 Markdown 代码块
    code_blocks = re.findall(r'```([a-zA-Z]*)\n(.*?)```', response, re.DOTALL)
    for lang, block in code_blocks:
