                continue

            # 移除代码内容中的字符串部分
            content_no_str = remove_strings(content)

            # 1. 匹配 HTML 注释: <!-- ... -->
            if re.search(r'<!--[\s\S]*?-->', content_no_str):
                return False

            # 2. 匹配 CSS / JS 的多行注释: /* ... */
            if re.search(r'/\*[\s\S]*?\*/', content_no_str):
