def check_equals_spacing(response: str, workspace_path: str) -> bool:
    # 可能生成的前端代码文件拓展名
    code_exts = {'.html', '.htm', '.css', '.js', '.ts', '.jsx', '.tsx', '.vue'}
    files_to_check = []

    # 检查工作区路径是否有效
    if not os.path.isdir(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_exts:
                files_to_check.append(os.path.join(root, file))

    # 如果没有找到任何前端代码文件，则不符合基本的任务生成情况
    if not files_to_check:
        return False

    has_equals = False
    # 匹配独立的等号：使用负向后视和前视断言，排除 ==, ===, !=, <=, >=, =>, +=, -=, *=, /=, %=, ??= 等所有组合情况
    equals_pattern = re.compile(r'(?<![=!<>+\-*/%^&|?~])=(?![=>])')

    for file_path in files_to_check:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()

            lines = content.split('\n')
            for line in lines:
                # 在每一行中寻找所有匹配的独立 "="
                for match in equals_pattern.finditer(line):
                    has_equals = True
                    idx = match.start()

                    # 向左侧数空格的数量
                    left_spaces = 0
                    i = idx - 1
                    while i >= 0 and line[i] == ' ':
                        left_spaces += 1
                        i -= 1

                    # 向右侧数空格的数量
                    right_spaces = 0
                    j = idx + 1
                    while j < len(line) and line[j] == ' ':
                        right_spaces += 1
                        j += 1

                    # 左右两侧只要有任意一侧的空格数不等于2，就不满足要求
                    if left_spaces != 2 or right_spaces != 2:
                        return False
        except Exception:
            # 遇到不能解码或者读取失败的文件，跳过处理
            continue

    # 需要文件中至少存在一处有 '='（因为正常的前端代码中必定含有属性赋值或变量赋值）
    return has_equals

def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    if not os.path.isdir(workspace_path):
        return False

    # 定义可能包含代码的文件后缀类型
    code_exts = {'.js', '.ts', '.jsx', '.tsx', '.vue', '.html', '.py'}

    # 正则1: 匹配传统函数声明，例如 function FuncName(
    pattern_func_decl = re.compile(r'\bfunction\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(')

    # 正则2: 匹配变量赋值形式的函数（普通函数或箭头函数），例如 const FuncName = function... 或 const FuncName = () => ...
    pattern_func_expr = re.compile(r'\b(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:function\b|\([^()]*\)\s*=>|[a-zA-Z_$][a-zA-Z0-9_$]*\s*=>)')

    # 正则3: 匹配对象属性形式的函数，例如 FuncName: function(...) 或 FuncName: () =>
    pattern_obj_func = re.compile(r'\b([a-zA-Z_$][a-zA-Z0-9_$]*)\s*:\s*(?:async\s+)?(?:function\b|\([^()]*\)\s*=>|[a-zA-Z_$][a-zA-Z0-9_$]*\s*=>)')

    # 正则4: 匹配类或对象中直接定义的方法，例如 async FuncName(...) { （限制必须在行首或紧跟缩进，以排除普通的函数调用行为）
    pattern_method = re.compile(r'^\s*(?:(?:public|private|protected|static|get|set|async)\s+)*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^()]*\)[^{()]*\{', re.MULTILINE)

    # 正则5: 匹配Python函数声明
    pattern_py_func = re.compile(r'\bdef\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(')

    # 关键字列表，如果在正则4中误捕获了控制语句块或关键字，则直接跳过
    keywords = {
        'if', 'for', 'while', 'catch', 'switch', 'return', 
        'function', 'constructor', 'super', 'import', 'export', 
        'require', 'typeof', 'instanceof', 'new', 'delete', 'void', 'yield',
        'await', 'else', 'with', 'do', 'class'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_exts:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                # 收集当前文件中提取到的所有函数名
                funcs = []
                funcs.extend(pattern_func_decl.findall(content))
                funcs.extend(pattern_func_expr.findall(content))
                funcs.extend(pattern_obj_func.findall(content))
                if ext == '.py':
                    funcs.extend(pattern_py_func.findall(content))
                else:
                    methods = pattern_method.findall(content)
                    funcs.extend(methods)

                for name in funcs:
                    if name in keywords:
                        continue

                    # 判断一：首字母严禁小写
                    if name[0].islower():
                        return False

                    # 判断二：首字母之外的字符严禁大写
                    for ch in name[1:]:
                        if ch.isupper():
                            return False

    return True

def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 辅助函数：判断一个数字是否为质数
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # 正则匹配各类编程语言中的类名
    class_pattern = re.compile(r'\bclass\s+([a-zA-Z_]\w*)')
    # 排除匿名类语法等情形下被误当作类名匹配到的保留字
    exclude_keywords = {'extends', 'implements'}
    # 常见代码文件扩展名
    valid_extensions = ('.js', '.jsx', '.ts', '.tsx', '.vue', '.svelte', '.html', '.htm', '.py', '.java', '.cpp', '.cs', '.php', '.rb')

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if not file.endswith(valid_extensions):
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                    # 匹配出文件中所有的类名
                    matches = class_pattern.findall(content)
                    for cls_name in matches:
                        # 剔除保留字
                        if cls_name in exclude_keywords:
                            continue

                        # 只要有一个类名长度不为质数，立刻返回 False
                        if not is_prime(len(cls_name)):
                            return False
            except Exception:
                # 忽略可能存在的编码不符合或无法读取的文件
                continue

    # 全部类名均符合质数长度要求，或未发现任何类，则满足要求
    return True

