import os
import re

def verify(response: str, workspace_path: str) -> bool:
    """
    遍历生成的代码项目并检查所有的代码文件中是否存在任何注释。
    如果发现注释则返回 False（代表不满足没有注释的要求）；
    如果全部没有注释则返回 True（代表满足要求）。
    """

    def remove_strings(code: str) -> str:
        # 优先去除可能出现的 Python 三引号字符串（多行）
        code = re.sub(r'"""(?:\\.|[^\\])*?"""', '""', code, flags=re.DOTALL)
        code = re.sub(r"'''(?:\\.|[^\\])*?'''", "''", code, flags=re.DOTALL)
        # 去除双引号、单引号、反引号包围的普通字符串
        code = re.sub(r'"(?:\\.|[^"\\])*"', '""', code, flags=re.DOTALL)
        code = re.sub(r"'(?:\\.|[^'\\])*'", "''", code, flags=re.DOTALL)
        code = re.sub(r'`(?:\\.|[^`\\])*`', '``', code, flags=re.DOTALL)
        return code

    def has_js_comments(code: str) -> bool:
        code = remove_strings(code)
        # 移除转义字符，避免影响类似 \/ 形式导致的误判
        code = re.sub(r'\\.', '', code)
        if re.search(r'/\*', code):
            return True
        if re.search(r'//', code):
            return True
        return False

    def has_css_comments(code: str) -> bool:
        code = remove_strings(code)
        code = re.sub(r'\\.', '', code)
        if re.search(r'/\*', code):
            return True
        return False

    def has_html_comments(code: str) -> bool:
        # 先提取并检查所有的 script 块
        scripts = re.findall(r'<script[^>]*>(.*?)</script>', code, flags=re.DOTALL | re.IGNORECASE)
        for s in scripts:
            if has_js_comments(s):
                return True

        # 提取并检查所有的 style 块
        styles = re.findall(r'<style[^>]*>(.*?)</style>', code, flags=re.DOTALL | re.IGNORECASE)
        for s in styles:
            if has_css_comments(s):
                return True

        # 删掉 script 和 style 块后，再寻找是否包含标准的 HTML 注释
        code = re.sub(r'<script[^>]*>.*?</script>', '', code, flags=re.DOTALL | re.IGNORECASE)
        code = re.sub(r'<style[^>]*>.*?</style>', '', code, flags=re.DOTALL | re.IGNORECASE)

        if re.search(r'<!--', code):
            return True
        return False

    def has_py_comments(code: str) -> bool:
        code = remove_strings(code)
        code = re.sub(r'\\.', '', code)
        if re.search(r'#', code):
            return True
        return False

    if not os.path.exists(workspace_path):
        return False

    # 遍历当前项目的工作区文件，检查各类代码文件是否留有注释
    for root, dirs, files in os.walk(workspace_path):
        for f in files:
            filepath = os.path.join(root, f)
            ext = os.path.splitext(f)[1].lower()

            try:
                with open(filepath, 'r', encoding='utf-8') as file:
                    content = file.read()
            except Exception:
                continue

            # 分门别类检查常规的前后端代码文件
            if ext in ['.js', '.jsx', '.ts', '.tsx', '.java', '.c', '.cpp', '.cs', '.h', '.hpp']:
                if has_js_comments(content):
                    return False
            elif ext in ['.css', '.scss', '.less']:
                if has_css_comments(content):
                    return False
            elif ext in ['.html', '.htm', '.vue']:
                if has_html_comments(content):
                    return False
            elif ext in ['.py']:
                if has_py_comments(content):
                    return False

    # 若完整检查未触发返回 False，则代码中无注释，验证通过
    return True

