                if content.strip():
                    found_any_code_file = True

                matches = pattern.finditer(content)
                for match in matches:
                    i = match.start()

                    # 1. 检查左侧是否有且仅有两个空格
                    if i < 2:
                        return False
                    if content[i-1] != ' ' or content[i-2] != ' ':
                        return False
                    # 确保第三个位置（若存在）不是空格，即“恰好”有两个空格
                    if i >= 3 and content[i-3] == ' ':
