    ]
    # 匹配类方法或对象方法定义，强制必须在行首起步以免误匹配局部调用
    class_method_pattern = r'^\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^)]*\)\s*\{'

    # 准备 Python 的正则表达式
    py_pattern = r'\bdef\s+([a-zA-Z_]\w*)\s*\('

