                content = re.sub(r'/\*[\s\S]*?\*/', '', content)
                content = re.sub(r'//.*', '', content)
            elif ext == '.py':
                content = re.sub(r'#.*', '', content)
                content = re.sub(r'\'\'\'[\s\S]*?\'\'\'', '', content)
                content = re.sub(r'\"\"\"[\s\S]*?\"\"\"', '', content)

            functions = []

            # 提取 JS/TS/HTML 的相关函数
            if ext in ['.js', '.ts', '.jsx', '.tsx', '.html', '.htm', '.vue', '.svelte']:
