                content = re.sub(r'/\*.*?\*/', '', content, flags=re.DOTALL)
                content = re.sub(r'<!--.*?-->', '', content, flags=re.DOTALL)

                # 剔除字符串内部的内容 (避免误判字符串文本中出现的 '=')
                content = re.sub(r'"(?:[^"\\]|\\.)*"', '""', content)
                content = re.sub(r"'(?:[^'\\]|\\.)*'", "''", content)
                content = re.sub(r'`(?:[^`\\]|\\.)*`', '``', content)

                lines = content.split('\n')
                for line in lines:
                    # 查找独立的 '='，排除 !=, ==, >=, +=, =>, 等复合运算符
                    for match in re.finditer(r'(?<![=!<>+\-*/%&|^~?:])=(?![=>])', line):
                        idx = match.start()

                        # 判断等号左侧是否恰好有2个空格
                        left_ok = False
                        if idx >= 2 and line[idx-1] == ' ' and line[idx-2] == ' ':
