                            if idx == 2 or line[idx-3] != ' ':
                                left_ok = True

                        # 判断等号右侧是否恰好有2个空格
                        right_ok = False
                        if idx + 2 < len(line) and line[idx+1] == ' ' and line[idx+2] == ' ':
                            # 第3个字符不是空格，或者是行尾
                            if idx + 3 == len(line) or line[idx+3] != ' ':
                                right_ok = True

                        # 如果有任何一侧的空格数不等于2，则不满足要求
                        if not (left_ok and right_ok):
                            return False

    return True

