import ast

def check_function_name_convention(response: str, workspace_path: str) -> bool:
    # 匹配普通函数声明，以及绑定了函数的常量/变量声明（箭头函数或匿名函数）
    js_func_pattern = re.compile(
        r'\bfunction\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(|'
        r'\b(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*(?::[^=;]+)?=\s*(?:function\b|\([^)]*\)\s*=>|[a-zA-Z_$][a-zA-Z0-9_$]*\s*=>)'
    )

    # 匹配Python函数声明
    py_func_pattern = re.compile(r'\bdef\s+([a-zA-Z_]\w*)\s*\(')

    allowed_extensions = {'.js', '.ts', '.jsx', '.tsx', '.html', '.htm', '.vue', '.svelte', '.py'}

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in allowed_extensions:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            func_names = []
            if ext == '.py':
                try:
                    tree = ast.parse(content)
                    for node in ast.walk(tree):
                        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            func_names.append(node.name)
                except Exception:
                    # AST解析失败时回退到正则提取
                    for m in py_func_pattern.finditer(content):
                        func_names.append(m.group(1))
            else:
                for m in js_func_pattern.finditer(content):
                    name = m.group(1) or m.group(2)
                    if name:
                        func_names.append(name)

            # 对当前文件中提取到的所有函数名进行大小写检查
            for name in func_names:
                if not name:
                    continue

                # 规则1：首字母严禁小写
                if name[0].islower():
                    return False

                # 规则2：首字母之外的字符严禁大写
                if len(name) > 1 and any(c.isupper() for c in name[1:]):
                    return False

    return True

