                # 判断文件名的字符个数是否严格等于奇数
                if len(file) % 2 == 0:
                    return False

    # 如果没有找到任何代码文件，说明可能未生成代码文件，算作验证失败
    return has_code_file

def check(response: str, workspace_path: str) -> bool:
    import os
    import re

    def has_comments(content: str, lang_type: str) -> bool:
        if lang_type in ['js', 'jsx', 'ts', 'tsx', 'vue', 'svelte', 'html', 'htm', 'json', 'c', 'cpp', 'h', 'hpp', 'java', 'go', 'rs']:
            # 去除字符串内容，防止字符串里的 // 或 /* 引起误判
            content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
            content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
            content = re.sub(r'`(?:\\`|[^`])*`', '``', content)

            # 匹配单行注释 // (且前面不是冒号，排除类似 http:// 未加引号的边缘情况)
            if re.search(r'(?<!:)\/\/.*', content):
                return True
            # 匹配多行注释 /* ... */
            if re.search(r'/\*[\s\S]*?\*/', content):
                return True
            # HTML 相关文件中匹配 <!-- ... -->
            if lang_type in ['html', 'htm', 'vue', 'svelte'] and re.search(r'<!--[\s\S]*?-->', content):
                return True

        elif lang_type == 'css':
            content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
            content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
            if re.search(r'/\*[\s\S]*?\*/', content):
                return True

        elif lang_type == 'py':
            # 优先去除多行字符串（Docstring）
            content = re.sub(r'"""[\s\S]*?"""', '""', content)
            content = re.sub(r"'''[\s\S]*?'''", "''", content)
            content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
            content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
            if re.search(r'#.*', content):
                return True

        return False

    # 1. 检查 workspace_path 下生成的代码文件
    if os.path.exists(workspace_path):
        code_extensions = {
            '.js': 'js', '.jsx': 'jsx', '.ts': 'ts', '.tsx': 'tsx',
            '.vue': 'vue', '.svelte': 'svelte', '.html': 'html', '.htm': 'htm',
            '.json': 'json', '.css': 'css', '.py': 'py', 
            '.c': 'c', '.cpp': 'cpp', '.h': 'h', '.hpp': 'hpp',
            '.java': 'java', '.go': 'go', '.rs': 'rs'
        }

        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in code_extensions:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()
                    except Exception:
                        continue

                    if has_comments(content, code_extensions[ext]):
                        return False

    # 2. 检查 response 中的代码块
    code_blocks = re.findall(r'```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```', response)

    lang_mapping = {
        'javascript': 'js', 'js': 'js',
        'typescript': 'ts', 'ts': 'ts',
        'jsx': 'jsx', 'tsx': 'tsx',
        'html': 'html', 'vue': 'vue', 'svelte': 'svelte',
        'json': 'json',
        'css': 'css',
        'python': 'py', 'py': 'py',
        'c': 'c', 'cpp': 'cpp', 'c++': 'cpp',
        'java': 'java', 'go': 'go', 'rust': 'rs', 'rs': 'rs'
    }

    for lang, content in code_blocks:
        lang_lower = lang.lower().strip()
        if lang_lower in lang_mapping:
            if has_comments(content, lang_mapping[lang_lower]):
                return False

    return True

