def check_indentation(response: str, workspace_path: str) -> bool:
    import os

    valid_exts = {
        '.js', '.ts', '.html', '.css', '.vue', '.jsx', '.tsx',
        '.json', '.py', '.java', '.c', '.cpp', '.h', '.hpp',
        '.go', '.rs', '.php', '.rb', '.sh'
    }

    if not os.path.exists(workspace_path) or not os.path.isdir(workspace_path):
        return False

    file_found = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_exts:
                file_found = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                in_comment = False
                in_html_comment = False
                in_template = False

                for line in lines:
                    stripped = line.strip()
                    # 忽略空行
                    if not stripped:
                        continue

                    # 提取该行的前导空白字符
                    leading_ws = line[:len(line) - len(line.lstrip())]

                    # 判定当前行是否属于可以豁免缩进检查的特殊块
                    is_exempt = in_comment or in_html_comment or in_template or stripped.startswith('*')

                    if not is_exempt:
                        # 不允许使用制表符
                        if '\t' in leading_ws:
                            return False
                        # 缩进空格数量必须为 4 的倍数
                        if len(leading_ws) % 4 != 0:
                            return False

                    # 更新多行块的状态
                    # JS / TS / CSS 等块级注释
                    if '/*' in stripped and '*/' not in stripped[stripped.find('/*'):]:
                        in_comment = True
                    elif '*/' in stripped:
                        in_comment = False

                    # HTML 块级注释
                    if '<!--' in stripped and '-->' not in stripped[stripped.find('<!--'):]:
                        in_html_comment = True
                    elif '-->' in stripped:
                        in_html_comment = False

                    # JS / TS 模板字符串 (`)
                    unescaped_backticks = line.replace('\\`', '').count('`')
                    if unescaped_backticks % 2 != 0:
                        in_template = not in_template

                    # Python 多行字符串
                    unescaped_triple_double = line.count('"""')
                    if unescaped_triple_double % 2 != 0:
                        in_template = not in_template

                    unescaped_triple_single = line.count("'''")
                    if unescaped_triple_single % 2 != 0:
                        in_template = not in_template

    return file_found

