def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    def check_content(content: str) -> bool:
        # 预处理：去除字符串字面量与各类注释，避免无关等号造成的误判
        # 去除包围在单引号、双引号、反引号中的字符串
        content = re.sub(r'(["\'`])(?:(?!\1)[^\\]|\\.)*\1', '""', content, flags=re.DOTALL)
        # 去除多行注释
        content = re.sub(r'/\*.*?\*/', '', content, flags=re.DOTALL)
        content = re.sub(r'<!--.*?-->', '', content, flags=re.DOTALL)
        # 去除单行注释
        content = re.sub(r'(//|#).*', '', content)

        # 匹配所有不属于复合运算符（如 ==, !=, >=, +=, => 等）的独立等于号
        pattern = re.compile(r'(?<![+\-\*/%<>=!&|^~])=(?![=>])')

        for match in pattern.finditer(content):
            start = match.start()
            end = match.end()

            # 检查等号左侧：必须恰好为 2 个连续空格，且再往左的字符不能是空格
            if start < 2:
                return False
            if content[start-2:start] != "  ":
                return False
            if start >= 3 and content[start-3] == " ":
                return False

            # 检查等号右侧：必须恰好为 2 个连续空格，且再往右的字符不能是空格
            if end + 2 > len(content):
                return False
            if content[end:end+2] != "  ":
                return False
            if end + 2 < len(content) and content[end+2] == " ":
                return False

        return True

    has_files = False
    # 推断常见可能生成的前端以及项目相关代码文件类型
    valid_extensions = (
        '.js', '.ts', '.jsx', '.tsx', '.vue', '.html', 
        '.css', '.scss', '.less', '.json', '.py', 
        '.java', '.c', '.cpp', '.h', '.hpp'
    )

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if not file.endswith(valid_extensions):
                continue

            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            has_files = True
            # 如果某个文件未满足要求，即刻返回 False
            if not check_content(content):
                return False

    # 至少要包含被检查的文件且全部满足条件，方可视为通过
    return has_files

import os
import re

def check_requirements(response: str, workspace_path: str) -> bool:
    if not os.path.exists(workspace_path):
        return False

    # 定义各类函数/方法提取的正则表达式
    patterns = [
        # 1. Python: def FuncName(
        re.compile(r'\b(?:async\s+)?def\s+([a-zA-Z_]\w*)\s*\('),
        # 2. JS/TS 普通函数: function FuncName( 或者 function* FuncName(
        re.compile(r'\b(?:async\s+)?function\s*\*?\s*([a-zA-Z_]\w*)\s*\('),
        # 3. JS/TS 变量赋值形式的函数 (包括箭头函数): const/let/var FuncName = () => 或者 = function
        re.compile(r'\b(?:const|let|var)\s+([a-zA-Z_]\w*)\s*=\s*(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[a-zA-Z_]\w*\s*=>)'),
        # 4. JS/TS 类属性箭头函数: public/private/static FuncName = () =>
        re.compile(r'^\s*(?:(?:public|private|protected|static)\s+)*(?:readonly\s+)?([a-zA-Z_]\w*)\s*=\s*(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[a-zA-Z_]\w*\s*=>)', re.MULTILINE),
    ]

    # 5. JS/TS 类方法提取: public/private/static MethodName() {
    method_pattern = re.compile(r'^\s*(?:(?:public|private|protected|static)\s+)*(?:async\s+)?([a-zA-Z_]\w*)\s*\([^)]*\)\s*\{', re.MULTILINE)

    # 语言关键字字典：防止类方法正则将控制流语法误认为是方法
    keywords = {
        'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'catch', 'finally', 
        'return', 'function', 'constructor', 'get', 'set', 'async', 'await',
        'import', 'export', 'default', 'class', 'extends', 'super', 'new',
        'this', 'typeof', 'instanceof', 'yield', 'delete', 'void', 'with', 'debugger'
    }

    def clean_code(code: str) -> str:
        """清理代码中的注释，防止注释中的示例代码导致误判"""
        # 移除多行注释和HTML注释
        code = re.sub(r'/\*.*?\*/', '', code, flags=re.DOTALL)
        code = re.sub(r'<!--.*?-->', '', code, flags=re.DOTALL)
        # 移除单行注释 (仅处理行首或前面是空白的注释)
        code = re.sub(r'^\s*//.*$', '', code, flags=re.MULTILINE)
        code = re.sub(r'^\s*#.*$', '', code, flags=re.MULTILINE)
        return code

    valid_extensions = {'.js', '.ts', '.jsx', '.tsx', '.py', '.html'}

    for root, dirs, files in os.walk(workspace_path):
        # 排除第三方依赖库和版本控制文件夹
        if 'node_modules' in root or '.git' in root:
            continue

        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in valid_extensions:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            content = clean_code(content)
            function_names = []

            # 使用基础正则模式提取
            for p in patterns:
                for match in p.finditer(content):
                    function_names.append(match.group(1))

            # 提取类方法，同时需要过滤掉保留关键字
            for match in method_pattern.finditer(content):
                name = match.group(1)
                if name not in keywords:
                    function_names.append(name)

            # 针对捕获到的每一个函数名进行逻辑验证
            for name in function_names:
                if not name:
                    continue
                # 规则 1：首字母严禁小写
                if name[0].islower():
                    return False
                # 规则 2：首字母之外的字符严禁大写
                for char in name[1:]:
                    if char.isupper():
                        return False

    return True

def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 辅助函数：判断给定的整数是否为质数
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # 常见可能包含类定义的前端与后端相关代码文件扩展名
    code_extensions = {
        '.js', '.ts', '.jsx', '.tsx', '.py', '.java', 
        '.cpp', '.h', '.c', '.cs', '.php', '.go', '.rb', 
        '.swift', '.kt', '.html', '.vue', '.svelte'
    }

    # 用于匹配大多数面向对象语言中类名的正则表达式
    # \bclass\s+ ：匹配独立的关键字 class 和其后的空白字符
    # ([a-zA-Z_][a-zA-Z0-9_]*) ：匹配合法的标识符作为类名
    class_pattern = re.compile(r'\bclass\s+([a-zA-Z_][a-zA-Z0-9_]*)\b')

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                        # 查找当前文件中所有的类名
                        matches = class_pattern.findall(content)
                        for class_name in matches:
                            # 判断类名的长度是否恰好为质数
                            if not is_prime(len(class_name)):
                                return False
                except Exception:
                    # 遇到无法使用utf-8读取等异常情况，跳过该文件继续验证其他文件
                    continue

    # 如果所有的类名长度均为质数（或代码中没有任何类定义），则满足要求
    return True

