def evaluate(response: str, workspace_path: str) -> bool:
    import os
    import re

    def has_comment(code: str, ext: str) -> bool:
        # 1. 剔除字符串字面量，避免内部带有注释符号的字符串造成误判
        # 包括双引号、单引号和反引号包裹的字符串内容
        code = re.sub(r'"(?:\\.|[^"\\])*"', '""', code)
        code = re.sub(r"'(?:\\.|[^'\\])*'", "''", code)
        code = re.sub(r'`(?:\\.|[^`\\])*`', '``', code)

        # 2. 检查 HTML 注释 (<!-- ... -->)
        if re.search(r'<!--[\s\S]*?-->', code):
            return True

        # 3. 检查块注释 (/* ... */) 排除前面存在反斜杠转义的情况
        if re.search(r'(?<!\\)/\*[\s\S]*?\*/', code):
            return True

        # 4. 检查单行注释 // (仅限前端及相关衍生类型代码)
        frontend_exts = {'.js', '.ts', '.jsx', '.tsx', '.html', '.htm', '.css', '.vue', '.svelte', '.scss', '.less'}
        if ext in frontend_exts:
            # (?<![\\:]) 排除转义的 \// 和 URL 形式的 ://
            if re.search(r'(?<![\\:])//.*', code):
                return True

        # 5. 检查 Python 等后续可能扩展的脚本注释 (#)
        if ext == '.py':
            for i, line in enumerate(code.split('\n')):
                # 排除第一行的 shebang 声明
                if i == 0 and line.startswith('#!'):
                    continue
                if re.search(r'#.*', line):
                    return True

        return False

    # 定义前端项目中常用的代码文件扩展名
    code_extensions = {'.js', '.ts', '.jsx', '.tsx', '.html', '.htm', '.css', '.vue', '.svelte', '.scss', '.less', '.py'}

    # 一、检查物理工作区实际生成的代码文件
    if os.path.exists(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in code_extensions:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            code_content = f.read()
                    except Exception:
                        continue

                    if has_comment(code_content, ext):
                        return False

    # 二、检查助手回复中呈现的 Markdown 代码块
    code_blocks = re.findall(r'```([a-zA-Z]*)\n([\s\S]*?)```', response)
    for lang, code_content in code_blocks:
        lang = lang.lower().strip()
        # 将明确的代码块语言映射为其对应的文件扩展名
        if lang in {'javascript', 'js'}: 
            ext = '.js'
        elif lang in {'typescript', 'ts'}: 
            ext = '.ts'
        elif lang in {'jsx'}: 
            ext = '.jsx'
        elif lang in {'tsx'}: 
            ext = '.tsx'
        elif lang in {'html'}: 
            ext = '.html'
        elif lang in {'css', 'scss', 'less'}: 
            ext = '.css'
        elif lang in {'vue'}: 
            ext = '.vue'
        elif lang in {'python', 'py'}: 
            ext = '.py'
        else:
            # 过滤掉 bash、shell、markdown 等未指定或非代码块，避免其特定语法造成误判
            continue  

        if has_comment(code_content, ext):
            return False

    return True

def check_utf8_encoding(response: str, workspace_path: str) -> bool:
    import os

    # 常见的前端及相关代码文件扩展名集合
    code_extensions = {
        ".html", ".css", ".js", ".ts", ".jsx", ".tsx", 
        ".json", ".md", ".vue", ".py", ".sh", ".bash", ".xml"
    }

