    # 定义需要检查的常规代码文件后缀
    code_extensions = {'.html', '.css', '.js', '.ts', '.jsx', '.tsx', '.vue', '.py', '.java', '.c', '.cpp', '.h'}
    checked_any_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                checked_any_code_file = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                # 状态机：用于跳过可能存在不规则缩进的多行字符串和多行注释内部
                in_block_comment = False
                in_py_string_double = False
                in_py_string_single = False
                in_js_template = False

                for line in lines:
                    stripped = line.lstrip()
                    if not stripped:
                        continue

                    # 1. 检查是否正在退出多行状态
                    if in_block_comment:
                        if '*/' in line:
                            in_block_comment = False
                        continue
                    if in_py_string_double:
                        if '"""' in line and line.count('"""') % 2 != 0:
                            in_py_string_double = False
                        continue
                    if in_py_string_single:
                        if "'''" in line and line.count("'''") % 2 != 0:
                            in_py_string_single = False
                        continue
                    if in_js_template:
                        if '`' in line and line.count('`') % 2 != 0:
                            in_js_template = False
                        continue

                    # 2. 检查是否进入多行状态（仅采用简单启发式判断，不考虑复杂嵌套和转义）
                    if '/*' in line and '*/' not in line:
                        in_block_comment = True
                    elif '"""' in line and line.count('"""') % 2 != 0:
                        in_py_string_double = True
                    elif "'''" in line and line.count("'''") % 2 != 0:
                        in_py_string_single = True
                    elif '`' in line and line.count('`') % 2 != 0:
                        in_js_template = True

                    # 3. 校验当前行的缩进
                    leading_spaces = len(line) - len(stripped)
                    leading_chars = line[:leading_spaces]

                    # 严格禁止使用制表符
                    if '\t' in leading_chars:
                        return False

                    # 前导空格必须为 4 的倍数
                    if leading_spaces % 4 != 0:
                        # 允许某些天然非 4 倍数且属于注释风格的行，比如 JSDoc 中的 " * " 或 HTML 注释
                        if stripped.startswith('*') or stripped.startswith('<!--') or stripped.startswith('-->'):
                            continue
                        return False

    return checked_any_code_file

