import os
import re

def verify(response: str, workspace_path: str) -> bool:
    if not os.path.exists(workspace_path):
        return False

    # 定义可以捕获大多数常见函数名定义的正则表达式
    func_patterns = [
        # JavaScript / TypeScript 标准 function 定义
        re.compile(r'\bfunction\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*\('),
        # JavaScript / TypeScript 匿名函数/箭头函数赋值形式
        re.compile(r'\b(?:const|let|var)\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[A-Za-z_$][A-Za-z0-9_$]*\s*=>)'),
        # Python def 函数定义
        re.compile(r'\bdef\s+([A-Za-z_][A-Za-z0-9_]*)\s*\('),
        # JavaScript / TypeScript 对象方法、类方法定义
        re.compile(r'(?:^|[\s{;])(?:async\s+)?([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^)]*\)\s*\{')
    ]

    # 需要过滤的语言保留关键字，防止正则误捕获
    keywords = {
        'if', 'for', 'while', 'switch', 'catch', 'function', 'return', 
        'constructor', 'else', 'elif', 'with', 'def', 'class', 'import', 
        'export', 'try', 'finally', 'yield', 'await', 'new', 'typeof'
    }

    has_code_files = False

    for root, dirs, files in os.walk(workspace_path):
        # 排除无需检查的依赖及配置目录
        if 'node_modules' in dirs:
            dirs.remove('node_modules')
        if '.git' in dirs:
            dirs.remove('.git')

        for file in files:
            # 针对常见的代码文件后缀名进行匹配
            if not file.endswith(('.js', '.ts', '.jsx', '.tsx', '.py', '.html', '.vue')):
                continue
            # 跳过压缩代码文件
            if file.endswith('.min.js'):
                continue

            has_code_files = True
            file_path = os.path.join(root, file)

            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            # 遍历并查找所有的函数名
            for pattern in func_patterns:
                matches = pattern.findall(content)
                for name in matches:
                    if name in keywords:
                        continue

                    if not name:
                        continue

                    # 规则1: 首字母严禁小写
                    if name[0].islower():
                        return False

                    # 规则2: 首字母之外的字符严禁大写
                    for char in name[1:]:
                        if char.isupper():
                            return False

    return has_code_files

def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # 匹配面向对象编程中的类名声明，如 class MyClass, class MyClass(Base), class MyClass extends...
    # \s+ 确保 class 和类名之间有空白符，能够避免误配 class="..." 的情况
    class_pattern = re.compile(r'\bclass\s+([a-zA-Z_]\w*)')

    # 常见的前端与后端代码文件扩展名
    code_extensions = (
        '.js', '.ts', '.jsx', '.tsx', 
        '.vue', '.html', '.py', 
        '.java', '.cs', '.cpp', '.hpp', '.c', '.h'
    )

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if file.endswith(code_extensions):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 查找当前文件中的所有类定义
                    matches = class_pattern.findall(content)
                    for class_name in matches:
                        # 判断类名长度是否恰好为质数
                        if not is_prime(len(class_name)):
                            return False
                except Exception:
                    # 忽略无法读取或非utf-8编码的文件，继续检查下一个文件
                    continue

    return True

def check_no_comments(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 按照注释风格对常见代码文件扩展名进行分类
    # 第一类：使用 //, /*, <!-- 作为注释的文件类型
    c_style_exts = {
        '.js', '.jsx', '.ts', '.tsx', '.vue', '.svelte', 
        '.html', '.htm', '.css', '.scss', '.less', 
        '.java', '.c', '.cpp', '.h', '.cs', '.go', '.rs'
    }
    # 第二类：使用 # 作为注释的文件类型
    script_style_exts = {
        '.py', '.sh', '.rb', '.yaml', '.yml', '.toml', '.ini'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            file_path = os.path.join(root, file)

            # 只处理指定类型的代码文件
            if ext not in c_style_exts and ext not in script_style_exts:
                continue

            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                # 忽略因非文本内容等原因无法通过 UTF-8 读取的文件
                continue

            if ext in c_style_exts:
                # 先剔除所有的字符串 (单/双/反引号)，防止字符串内部存在 URL 等引发误判
                text = re.sub(r'"(?:\\.|[^"\\])*"', '', content)
                text = re.sub(r"'(?:\\.|[^'\\])*'", '', text)
                text = re.sub(r'`(?:\\.|[^`\\])*`', '', text)

                # 检查是否存在注释符号
                if '<!--' in text:
                    return False
                if '//' in text:
                    return False
                if '/*' in text:
                    return False

            elif ext in script_style_exts:
                # 剔除 Python 风格的多行字符串和普通字符串，防止其中的 # 导致误判
                text = re.sub(r'"""(.*?)"""', '', content, flags=re.DOTALL)
                text = re.sub(r"'''(.*?)'''", '', text, flags=re.DOTALL)
                text = re.sub(r'"(?:\\.|[^"\\])*"', '', text)
                text = re.sub(r"'(?:\\.|[^'\\])*'", '', text)

                # 检查是否存在注释符号
                if '#' in text:
                    return False

    return True

import os
import re

def verify(response: str, workspace_path: str) -> bool:
    def remove_strings_and_comments(code: str) -> str:
        # 移除双引号、单引号、反引号包围的字符串（跳过转义的引号）
        code = re.sub(r'"(?:\\.|[^"\\])*"', '""', code)
        code = re.sub(r"'(?:\\.|[^'\\])*'", "''", code)
        code = re.sub(r'`(?:\\.|[^`\\])*`', '``', code)
        # 移除各类代码注释
        code = re.sub(r'//.*', '', code)
        code = re.sub(r'/\*[\s\S]*?\*/', '', code)
        code = re.sub(r'#.*', '', code)
        return code

    found_any_var = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            # 仅校验常见可能包含变量的代码文件
            if file.endswith(('.js', '.ts', '.jsx', '.tsx', '.html', '.vue', '.py')):
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                script_contents = []
                # HTML 和 Vue 文件中，我们只关心 <script> 标签包裹的代码逻辑部分
                if file.endswith(('.html', '.vue')):
                    scripts = re.findall(r'<script[^>]*>([\s\S]*?)</script>', content, re.IGNORECASE)
                    script_contents.extend(scripts)
                else:
                    script_contents.append(content)

                for script in script_contents:
                    # 在进行变量匹配前，移除字符串内容与注释，防止关键字干扰
                    clean_script = remove_strings_and_comments(script)

                    if file.endswith('.py'):
                        # 匹配 Python 变量赋值，例如： "    poi_var = 1"
                        matches = re.findall(r'^[ \t]*([a-zA-Z_][a-zA-Z0-9_]*)\s*=(?!=)', clean_script, flags=re.MULTILINE)
                        for var_name in matches:
                            found_any_var = True
                            if not var_name.startswith('poi_'):
                                return False
                    else:
                        # 匹配 JS/TS 变量声明：匹配 var, let, const 后的第一个变量名
                        matches = re.findall(r'\b(?:var|let|const)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b', clean_script)
                        for var_name in matches:
                            found_any_var = True
                            if not var_name.startswith('poi_'):
                                return False

    # 若未找到任何变量，则判断为未实际满足开发需求（地图功能等必然产生变量）
    return found_any_var

