def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 定义前端项目常见的代码文件扩展名
    code_exts = {'.html', '.js', '.ts', '.css', '.jsx', '.tsx', '.vue'}
    has_code_file = False

    # 正则表达式：匹配独立的 "=" 号
    # 排除左侧为 = ! < > + - * / % & | ^ ~ ? 的情况（复合赋值或比较运算符）
    # 排除右侧为 = > 的情况（==, ===, => 等）
    pattern = re.compile(r"(?<![=!<>+\-*/%&|^~?-])=(?![=>])")

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if any(file.endswith(ext) for ext in code_exts):
                has_code_file = True
                file_path = os.path.join(root, file)
