                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                matches = pattern.finditer(content)
                for match in matches:
                    index = match.start()

                    # 检查左侧：必须恰好有两个空格
                    if index < 2:
                        return False
                    if content[index-1] != ' ' or content[index-2] != ' ':
                        return False
                    # 左侧第三个字符不能是空格（确保只有两个空格）
                    if index >= 3 and content[index-3] == ' ':
                        return False

                    # 检查右侧：必须恰好有两个空格
                    if index > len(content) - 3:
                        return False
                    if content[index+1] != ' ' or content[index+2] != ' ':
                        return False
                    # 右侧第三个字符不能是空格（确保只有两个空格）
                    if index <= len(content) - 4 and content[index+3] == ' ':
                        return False

    # 只有在存在代码文件且所有文件中的 '=' 都符合要求时，才返回 True
