def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    if not os.path.exists(workspace_path):
        return False

    def remove_strings(text: str) -> str:
        # 移除代码内容中的双引号、单引号和反引号内的字符串，防止字符串内部出现注释符号导致误判
        text = re.sub(r'"(?:\\.|[^"\\])*"', '""', text)
        text = re.sub(r"'(?:\\.|[^'\\])*'", "''", text)
        text = re.sub(r'`(?:\\.|[^`\\])*`', '``', text)
        return text

    def remove_urls(text: str) -> str:
        # 移除无引号情况下的外部 URL 格式，以避免 http:// 的双斜杠被当作单行注释
        text = re.sub(r'https?://', '', text)
        text = re.sub(r'url\s*\(\s*//', 'url(', text)
        return text

    # 定义前端及常见后台相关的代码文件类型
    code_exts = {
        '.js', '.ts', '.jsx', '.tsx', '.vue', '.html', '.htm', 
        '.css', '.scss', '.sass', '.less', 
        '.py', '.sh', '.bash', '.yml', '.yaml'
    }

    checked_files_count = 0

    for root, dirs, files in os.walk(workspace_path):
        # 排除掉常见的版本控制、依赖安装包和编译产物目录
        if any(exclude in root for exclude in ['.git', 'node_modules', '__pycache__', 'dist', 'build']):
            continue

        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in code_exts:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            # 对文件内容清洗后再匹配注释
            content_no_str = remove_urls(content)
            content_no_str = remove_strings(content_no_str)

            checked_files_count += 1

            # 1. 检查多行注释 /* ... */
            if '/*' in content_no_str and '*/' in content_no_str:
                return False

            # 2. 检查 HTML/Vue 模板注释 <!-- ... -->
            if '<!--' in content_no_str:
                return False

            # 3. 检查 JS/TS/CSS 等相关文件中的单行注释 //
            if ext in {'.js', '.ts', '.jsx', '.tsx', '.vue', '.css', '.scss', '.sass', '.less', '.html', '.htm'}:
                # 使用负向后视断言 (?<!:)//，进一步杜绝匹配到非常规拼接的 file:// 等伪协议
                if re.search(r'(?<!:)//', content_no_str):
                    return False

            # 4. 检查 Python/Shell/YAML 中的单行注释 #
            if ext in {'.py', '.sh', '.bash', '.yml', '.yaml'}:
                # (?:^|\s)# 匹配行首或者前面是空白字符的井号，避免匹配掉非代码区域的其他用途字符
                if re.search(r'(?:^|\s)#', content_no_str, re.MULTILINE):
                    return False

    # 当且仅当至少检查了一个代码文件，并且其中没有任何文件包含注释时返回 True
    return checked_files_count > 0

import os
