def check_variable_naming_rule(response: str, workspace_path: str) -> bool:
    # 匹配 let, const, var 声明的单个变量名
    # 正则释义：匹配 let/const/var 关键字，后跟至少一个空格，然后捕获合法的JS变量名
    var_pattern = re.compile(r'\b(?:let|const|var)\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\b')

    def is_valid_vars(code_content: str) -> bool:
        # 在检查前简单移除多行和单行注释，避免对注释内容误判
        code_no_comments = re.sub(r'/\*.*?\*/', '', code_content, flags=re.DOTALL)
        code_no_comments = re.sub(r'//.*', '', code_no_comments)

        # 查找所有匹配的普通变量声明
        matches = var_pattern.findall(code_no_comments)
        for var_name in matches:
            if not var_name.startswith('trip_'):
                return False
        return True

    # 1. 检查最后一轮回复中提供的所有代码块
    # 提取 Markdown 格式的代码块内容
    code_blocks = re.findall(r'```[a-zA-Z]*\n(.*?)```', response, re.DOTALL)
    for block in code_blocks:
        if not is_valid_vars(block):
            return False

    # 2. 检查生成的代码项目中的代码文件
    if os.path.exists(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            # 排除前端依赖与版本控制目录
            if 'node_modules' in root or '.git' in root:
                continue

            for file in files:
                # 针对常见的前端文件进行验证
                if file.endswith(('.js', '.ts', '.jsx', '.tsx', '.vue', '.html')):
                    filepath = os.path.join(root, file)
                    try:
                        with open(filepath, 'r', encoding='utf-8') as f:
                            content = f.read()

                        # 如果在文件中找到任何未遵循规则的变量名，直接返回 False
                        if not is_valid_vars(content):
                            return False
                    except Exception:
                        # 对于偶然不可读的文件予以忽略
                        continue

    # 如果所有提取出的变量声明都以 trip_ 开头，则满足要求
    return True

