                        stripped_line = line.lstrip()
                        leading_spaces = line[:len(line) - len(stripped_line)]

                        if not leading_spaces:  # 没有缩进，直接通过
                            continue

                        # 缩进必须全为空格，严禁包含制表符(\t)等其它空白字符
                        if not all(c == ' ' for c in leading_spaces):
