def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 定义需要进行检查的常见代码文件扩展名
    valid_extensions = {
        '.js', '.ts', '.jsx', '.tsx', '.vue', '.html', '.css', 
        '.scss', '.less', '.py', '.sh', '.xml'
    }

    # 匹配规则：用于提取出所有的字符串和注释进行过滤，避免内部等号造成误判
    # 1. 字符串: "..." 或 '...' 或 `...` (支持多行)
    # 2. 多行注释: /* ... */ 或 <!-- ... -->
    # 3. 单行注释: // ... 或 # ...
    pattern = re.compile(
        r'(?P<string>"(?:\\.|[^"\\\n])*"|\'(?:\\.|[^\'\\\n])*\'|`[\s\S]*?`)'
        r'|(?P<ml_comment>/\*[\s\S]*?\*/|<!--[\s\S]*?-->)'
        r'|(?P<sl_comment>//.*|#.*)',
        re.MULTILINE
    )

    # 替换函数：将其全部替换为等长的 'X'，保证位置索引不变且内部的特殊字符被安全遮蔽
    def replacer(match):
        return 'X' * len(match.group(0))

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        code = f.read()
                except Exception:
                    continue

                # 预处理：去掉注释和字符串中的干扰等号
                cleaned_code = pattern.sub(replacer, code)

                # 遍历处理后的代码，检查每一个 '=' 号
                for i, char in enumerate(cleaned_code):
                    if char == '=':
                        prev_char = cleaned_code[i-1] if i > 0 else ''
                        next_char = cleaned_code[i+1] if i < len(cleaned_code)-1 else ''

                        # 排除复合运算符（如 +=, ==, => 等）中的 =，只检查单等号
                        if prev_char in ('<', '>', '=', '!', '+', '-', '*', '/', '%', '&', '|', '^', '~', ':'):
                            continue
                        if next_char in ('=', '>'):
                            continue

                        # 检查左侧是否有且仅有两个空格
                        left_spaces = 0
                        left_idx = i - 1
                        while left_idx >= 0:
                            if cleaned_code[left_idx] == ' ':
                                left_spaces += 1
                                left_idx -= 1
                            elif cleaned_code[left_idx] in ('\t', '\n', '\r'):
                                left_spaces = -1  # 遇到换行或制表符，破坏了只有两个空格的规则
                                break
                            else:
                                break

                        # 检查右侧是否有且仅有两个空格
                        right_spaces = 0
                        right_idx = i + 1
                        while right_idx < len(cleaned_code):
                            if cleaned_code[right_idx] == ' ':
                                right_spaces += 1
                                right_idx += 1
                            elif cleaned_code[right_idx] in ('\t', '\n', '\r'):
                                right_spaces = -1  # 遇到换行或制表符，破坏了只有两个空格的规则
                                break
                            else:
                                break

                        # 如果非严格符合各有两个空格，直接判定为违反该要求
                        if left_spaces != 2 or right_spaces != 2:
                            return False

    return True

import os
import re
import ast

def verify(response: str, workspace_path: str) -> bool:
    # 可能被误识别为类/对象方法的保留字或控制流关键字，用作过滤
    keywords = {
        'if', 'for', 'while', 'switch', 'catch', 'finally', 'return', 
        'constructor', 'function', 'class', 'import', 'export', 'super', 
        'this', 'typeof', 'instanceof', 'void', 'delete', 'new', 'with', 
        'yield', 'await', 'else', 'try', 'do', 'length', 'push', 'map', 
        'filter', 'reduce'
    }

    # 正则表达式用于前端 JS/TS 的各类函数声明捕获
    # 1. 匹配标准 function 声明: function My_func(...) 或 function My_func<T>(...)
    js_func_re = re.compile(r'\bfunction\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*[\(\<]')
    # 2. 匹配箭头函数声明赋值: const My_func = (...) => 或 let My_func: ... = async () =>
    js_arrow_re = re.compile(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*(?::\s*[a-zA-Z0-9_<>, \t\[\]]+)?\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_][a-zA-Z0-9_]*)\s*=>')
    # 3. 匹配类/对象方法的简写模式: My_method(...) { (匹配行首或仅有修饰符)
    js_method_re = re.compile(r'^\s*(?:public\s+|private\s+|protected\s+|static\s+|async\s+|get\s+|set\s+)*([a-zA-Z_][a-zA-Z0-9_]*)\s*(?:<[^>]+>\s*)?\([^)]*\)\s*(?::\s*[^\{]+)?\s*\{', re.MULTILINE)

    valid_extensions = {'.js', '.ts', '.jsx', '.tsx', '.py', '.vue', '.html'}

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    funcs = []
                    # 针对 Python 文件的提取
                    if ext == '.py':
                        try:
                            tree = ast.parse(content)
                            for node in ast.walk(tree):
                                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                                    funcs.append(node.name)
                        except Exception:
                            py_func_re = re.compile(r'\bdef\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(')
                            funcs.extend(py_func_re.findall(content))

                    # 针对前端 JS/TS/Vue 等文件的提取
                    else:
                        funcs.extend(js_func_re.findall(content))
                        funcs.extend(js_arrow_re.findall(content))
                        methods = js_method_re.findall(content)
                        for m in methods:
                            if m not in keywords:
                                funcs.append(m)

                    # 去重并统一进行规则判断
                    for name in set(funcs):
                        if not name:
                            continue

                        # 1. 首字母严禁小写
                        if name[0].islower():
                            return False

                        # 2. 首字母之外的字符严禁大写
                        if len(name) > 1:
                            if any(c.isupper() for c in name[1:]):
                                return False

                except Exception:
                    # 如果遇到不可读取的文件等异常则跳过
                    continue

    # 如果全遍历完依然没有违反命名规范的函数，返回True
    return True

def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 判断数字是否为质数的函数
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # 正则表达式匹配主流编程语言中的类定义（例如: class MyClass {...}）
    class_pattern = re.compile(r'\bclass\s+([A-Za-z_][A-Za-z0-9_]*)\b')

    # 待检查的代码文件后缀类型
    valid_extensions = {
        '.js', '.ts', '.jsx', '.tsx', 
        '.html', '.vue', '.css', 
        '.py', '.java', '.cs', '.cpp', '.hpp', '.h'
    }

    # 忽略的系统文件夹或依赖目录
    ignore_dirs = {'.git', 'node_modules', '__pycache__', 'dist', 'build', 'out', '.idea', '.vscode'}

    for root, dirs, files in os.walk(workspace_path):
        # 移除不需要遍历的目录
        dirs[:] = [d for d in dirs if d not in ignore_dirs]

        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 查找所有定义的类名
                    matches = class_pattern.findall(content)
                    for class_name in matches:
                        # 检查当前类名长度是否为质数
                        if not is_prime(len(class_name)):
                            return False
                except Exception:
                    # 忽略无法正常按照utf-8读取或其它系统级异常的文件
                    continue

    # 若没有任何违背条件的类名，则视为满足要求
    return True

