        return True

    for root, dirs, files in os.walk(workspace_path):
        # 排除常见的无关目录，避免扫描产生的噪音和性能浪费
        for exclude_dir in ['node_modules', '.git', 'dist', 'build']:
            if exclude_dir in dirs:
                dirs.remove(exclude_dir)

        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_exts:
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    # 如果无法按 UTF-8 读取则直接跳过
                    continue

                # 移除代码内容中的字符串，避免将字符串内的 // 或 /* 当作注释误判
                content_no_str = str_pattern.sub('""', content)

                # 开始检查是否存在注释
                if ext == '.py':
                    if py_comment_pattern.search(content_no_str):
                        return False
                else:
                    if multiline_comment_pattern.search(content_no_str):
                        return False
                    if singleline_comment_pattern.search(content_no_str):
                        return False

    # 若所有文件都未找到注释，则满足要求
    return True

import os
import re

def verify_variable_naming_convention(response: str, workspace_path: str) -> bool:
    """
    验证项目中所有的变量名称是否都以 trip_ 开头
    """
    # 定义需要被检查的常见前端与后端代码文件后缀名
    valid_exts = {'.js', '.ts', '.jsx', '.tsx', '.vue', '.html', '.py'}

    # 匹配 JS/TS 等前端代码中的基本变量声明
    # 匹配示例: let trip_var = 1; const trip_var2 = 'test';
    pattern_js_var = re.compile(r'\b(?:let|const|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b')

    # 匹配 Python 代码中的基本变量声明
    # 匹配示例: trip_var = 1
    pattern_py_var = re.compile(r'^[ \t]*([a-zA-Z_][a-zA-Z0-9_]*)\s*=', re.MULTILINE)

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_exts:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    if ext == '.py':
                        # 检查 Python 脚本中的变量
                        matches = pattern_py_var.findall(content)
                        for var_name in matches:
                            if not var_name.startswith('trip_'):
                                return False
                    else:
                        # 对于 JS/TS/Vue/HTML，提取脚本中所有的 let/const/var 变量声明
                        matches = pattern_js_var.findall(content)
                        for var_name in matches:
                            if not var_name.startswith('trip_'):
                                return False

                except Exception:
                    # 忽略无法成功读取或解码的文件
                    continue

    # 如果项目中所有提取到的变量都以 trip_ 开头，或是未能成功提取到冲突的变量，则认为该要求满足
    return True
